// Some portions generated by Claude
import test from "node:test";
import assert from "node:assert/strict";
import { existsSync, readFileSync } from "node:fs";
import { graphTurtle } from "../../../main/frontend/graph-explorer/graph-export.ts";
import {
  expectedCountsText,
  exportFixtureGraph,
  fixtureDirectory,
  queryFixtures,
} from "../../../../scripts/export-query-fixtures.mjs";

// GraphExplorerQueryTest (JUnit) runs the committed .rq files; they must be what the generators produce today.
test("the committed query fixtures match the generators (run `npm run fixtures:queries` after changing them)", () => {
  const fixtures = queryFixtures();
  assert.ok(fixtures.length >= 16);
  for (const [name, query] of fixtures) {
    const file = `${fixtureDirectory}${name}.rq`;
    assert.ok(existsSync(file), `${name}.rq is missing`);
    assert.equal(readFileSync(file, "utf8").trimEnd(), query.trimEnd(), `${name}.rq is stale`);
  }
  assert.equal(readFileSync(`${fixtureDirectory}expected-counts.properties`, "utf8"), expectedCountsText(fixtures));
  assert.equal(readFileSync(`${fixtureDirectory}graph-export.ttl`, "utf8"), graphTurtle(exportFixtureGraph()), "graph-export.ttl is stale");
});
